// The per-request CSP nonce generated by src/start.ts is exposed to the client through
// <meta property="csp-nonce">, the same tag TanStack Router reads for its own scripts.
export function cspNonce(): string | undefined {
  if (typeof document === "undefined") return undefined;
  return document.querySelector('meta[property="csp-nonce"]')?.getAttribute("content") || undefined;
}
